/* Period indicates the sequential filling of each electron orbital.
   Electrons fill from the lowest energy levels to highest ones.
   Elements in a Period have the same number of electron shells. */
CREATE TABLE Period -- horizontal rows
    ( 
     period_id NUMBER 
                    ,
     number_of_electrons NUMBER -- number of electrons that occupy that period
    ) 
;

ALTER TABLE Period 
    ADD CONSTRAINT Period_period_id_UN UNIQUE ( period_id ) ;
    
