DROP TABLE Element;
DROP TABLE Category;
DROP TABLE Period;


-- Average atomic mass by category
SELECT c.category_name, AVG(e.atomic_mass) AS avg_atomic_mass
FROM Element e
JOIN Category c ON e.Category_category_id = c.category_id
GROUP BY c.category_name;

-- Count of elements per period
SELECT p.period_id, COUNT(e.atomic_number) AS element_count
FROM Element e
JOIN Period p ON e.Period_period_id = p.period_id
GROUP BY p.period_id
ORDER BY p.period_id;

/* Minimal goal: write queries to demonstrate calculations through aggregate functions */
-- The COUNT(*) function is introduced in the textbook on page 92
-- This query finds the count of elements per group
SELECT group_number, group_name, COUNT(*) AS element_count
FROM Element
GROUP BY group_number, group_name
ORDER BY group_number;

/* Due to the series of inner transition elements occupying group (i.e. column) 
   3 on the periodic table, a series which spans across 14 columns and is thus 
   displayed as two rows at the very bottom, the results of the previous query 
   showed duplicates in the group_number column. Therefore, to craft a more 
   advanced query which removes these duplicates, I prompted Claude to generate
   a more advanced query. Cladue used the "CASE" statement, something that was 
   mentioned in our textbook on pages 384-385. */
SELECT group_number,
       CASE WHEN group_name IN ('Lanthanide, or, inner transition element',
                                'Actinide, or, inner transition element')
            THEN 'Inner transition element'
            ELSE group_name
       END AS group_name,
       COUNT(*) AS element_count
FROM Element
GROUP BY group_number,
         CASE WHEN group_name IN ('Lanthanide, or, inner transition element',
                                  'Actinide, or, inner transition element')
              THEN 'Inner transition element'
              ELSE group_name
         END
ORDER BY group_number;

-- The MAX() and MIN() functions are introduced in the textbook on page 92
-- This query finds the maximum and minimum atomic mass per category
SELECT c.category_name,
       MAX(e.atomic_mass) AS "Max. Atomic Mass",
       MIN(e.atomic_mass) AS "Min. Atomic Mass"
FROM Element e
JOIN Category c ON e.Category_category_id = c.category_id
GROUP BY c.category_name;

-- Subquery: elements with atomic mass above the average
SELECT element_name, atomic_mass
FROM Element
WHERE atomic_mass > (SELECT AVG(atomic_mass) FROM Element) -- nested part runs first
ORDER BY atomic_mass;

-- View: element names with their category and period
CREATE VIEW Element_Summary AS
SELECT e.element_name, e.symbol, c.category_name, p.period_id
FROM Element e
JOIN Category c ON e.Category_category_id = c.category_id
JOIN Period p ON e.Period_period_id = p.period_id;
SELECT * FROM Element_Summary; -- access the view

-- Attempt to delete a category referenced by elements;
-- the foreign key constraint will prevent this
DELETE FROM Category WHERE category_id = 1;

-- Query demonstrating the category_description and number_of_electrons
-- attributes recommended by Mr. Dolphay
SELECT e.element_name, e.symbol, c.category_name, c.category_description,
       p.period_id, p.number_of_electrons
FROM Element e
JOIN Category c ON e.Category_category_id = c.category_id
JOIN Period p ON e.Period_period_id = p.period_id
WHERE e.atomic_number <= 10
ORDER BY e.atomic_number;

